-- Verified, versioned statutory parameters and native cumulative payroll projections.
-- No current statutory rates, thresholds or eligibility defaults are seeded here.
CREATE TABLE ty_pay_stat_config(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,
 person_id bigint,employment_id bigint,kind text NOT NULL CHECK(kind IN('policy','enrollment','opening','batch_period')),
 stable_key text NOT NULL,revision int NOT NULL CHECK(revision>0),system text NOT NULL CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','superseded','rejected')),
 valid_from date NOT NULL,valid_to date,data jsonb NOT NULL,evidence_ref text NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(approved_by IS NULL OR approved_by<>created_by),
 CHECK(status<>'approved' OR approved_by IS NOT NULL AND approved_at IS NOT NULL),UNIQUE(group_id,kind,stable_key,revision)
);
CREATE FUNCTION fn_ty_pay_stat_config_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE e public.ty_employment%ROWTYPE;b public.ty_pay_batch%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税参数及期初核定历史不能删除';END IF;
 IF TG_OP='UPDATE' AND(to_jsonb(NEW)-'status'-'approved_by'-'approved_at' IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at' OR OLD.status IN('approved','superseded')AND(to_jsonb(NEW)-'status' IS DISTINCT FROM to_jsonb(OLD)-'status' OR NEW.status NOT IN('approved','superseded')))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税已核参数须新版本修订，不覆盖旧版';END IF;
 IF NEW.kind='batch_period'THEN
  SELECT * INTO b FROM public.ty_pay_batch WHERE id=(NEW.data->>'batch_id')::bigint;
  IF b.id IS NULL OR b.group_id<>NEW.group_id OR b.company_id<>NEW.company_id OR b.system<>NEW.system OR b.status='confirmed'OR extract(day FROM(NEW.data->>'tax_period')::date)<>1 OR extract(day FROM(NEW.data->>'contribution_period')::date)<>1 OR date_trunc('month',(NEW.data->>'expected_payment_date')::date)::date<>(NEW.data->>'tax_period')::date THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税期间须与同主体未封存批次和预计支付月一致';END IF;
 END IF;
 IF NEW.employment_id IS NOT NULL THEN SELECT * INTO e FROM public.ty_employment WHERE id=NEW.employment_id;IF e.person_id IS DISTINCT FROM NEW.person_id OR e.company_id<>NEW.company_id OR e.group_id<>NEW.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税核定人员/雇佣/公司不一致';END IF;END IF;
 IF NEW.kind IN('enrollment','opening')AND NEW.person_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员薪税资格及期初须绑定永久人员';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_stat_config_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_stat_config FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_config_guard();
CREATE TABLE ty_pay_stat_root(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),person_id bigint NOT NULL,
 subject_key text NOT NULL,legal_employer_key text NOT NULL,plan_key text NOT NULL,component text NOT NULL,period date NOT NULL,global_key text NOT NULL UNIQUE,
 opening_id bigint NOT NULL REFERENCES ty_pay_stat_config(id),head_revision int NOT NULL DEFAULT 0,current_target numeric(24,2) NOT NULL CHECK(current_target>=0),
 latest_period date,last_batch_id bigint REFERENCES ty_pay_batch(id),last_assessment jsonb NOT NULL DEFAULT '{}'::jsonb,
 FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),UNIQUE(group_id,person_id,subject_key,legal_employer_key,plan_key,component,period)
);
CREATE FUNCTION fn_ty_pay_stat_root_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 IF TG_OP='DELETE'OR to_jsonb(NEW)-'head_revision'-'current_target'-'latest_period'-'last_batch_id'-'last_assessment' IS DISTINCT FROM to_jsonb(OLD)-'head_revision'-'current_target'-'latest_period'-'last_batch_id'-'last_assessment' OR NEW.head_revision<>OLD.head_revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税主体累计根只能按已确认工资版本前进';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_stat_root_guard BEFORE UPDATE OR DELETE ON ty_pay_stat_root FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_root_guard();
CREATE TABLE ty_pay_stat_reservation(
 adoption_id bigint PRIMARY KEY REFERENCES ty_pay_adoption(id),root_id bigint NOT NULL REFERENCES ty_pay_stat_root(id),batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),
 expected_revision int NOT NULL,state text NOT NULL CHECK(state IN('reserved','confirmed','released')),
 global_target numeric(24,2)NOT NULL CHECK(global_target>=0),local_target numeric(24,2)NOT NULL CHECK(local_target>=0),assessment jsonb NOT NULL
);
CREATE UNIQUE INDEX ty_pay_stat_one_active ON ty_pay_stat_reservation(root_id)WHERE state='reserved';
CREATE TRIGGER ty_pay_stat_reservation_immutable BEFORE DELETE ON ty_pay_stat_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();

-- The input lines are server-calculated targets. At final confirmation they are
-- reconstructed from real adoption/items; client verified labels are never authority.
CREATE FUNCTION fn_ty_pay_stat_context(p_batch bigint,p_employment bigint,p_enrollment bigint,p_lines jsonb)RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE b public.ty_pay_batch%ROWTYPE;e public.ty_employment%ROWTYPE;n public.ty_pay_stat_config%ROWTYPE;p public.ty_pay_stat_config%ROWTYPE;o public.ty_pay_stat_config%ROWTYPE;bp public.ty_pay_stat_config%ROWTYPE;rel public.ty_pay_config%ROWTYPE;
 x record;j jsonb;policy jsonb;vals jsonb:='[]'::jsonb;seen text[]:='{}';periods text[]:='{}';income numeric:=0;deductible numeric:=0;basic numeric:=0;special numeric:=0;other numeric:=0;v numeric;scope text;on_period date;cutoff date;subject text;typ text;pp jsonb;
BEGIN
 SELECT * INTO b FROM public.ty_pay_batch WHERE id=p_batch;SELECT * INTO e FROM public.ty_employment WHERE id=p_employment;SELECT * INTO n FROM public.ty_pay_stat_config WHERE id=p_enrollment;
 IF b.id IS NULL OR e.group_id<>b.group_id OR e.company_id<>b.company_id OR n.kind<>'enrollment'OR n.status<>'approved'OR n.group_id<>b.group_id OR n.person_id<>e.person_id OR n.system<>b.system THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税资格须属于本集团永久人员及本体系真实雇佣';END IF;
 SELECT * INTO p FROM public.ty_pay_stat_config WHERE id=(n.data->>'policy_id')::bigint;SELECT * INTO o FROM public.ty_pay_stat_config WHERE id=(n.data->>'opening_id')::bigint;
 IF p.kind<>'policy'OR p.status<>'approved'OR p.group_id<>b.group_id OR p.system<>b.system OR o.kind<>'opening'OR o.status<>'approved'OR o.person_id<>e.person_id OR o.group_id<>b.group_id OR o.system<>b.system THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税政策或期初未独立核准/不属于同一永久人员';END IF;
 SELECT * INTO bp FROM public.ty_pay_stat_config WHERE kind='batch_period'AND status='approved'AND(data->>'batch_id')::bigint=b.id ORDER BY revision DESC,id DESC LIMIT 1;
 IF bp.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资归属月、预计支付日、税款月和供款月须分别核定';END IF;
 typ:=p.data->>'type';on_period:=CASE WHEN typ='CN_IIT'THEN(bp.data->>'tax_period')::date ELSE(bp.data->>'contribution_period')::date END;cutoff:=(o.data->>'cutoff_period')::date;
 subject:=CASE WHEN typ='CN_IIT'THEN b.tax_subject_key ELSE b.contribution_subject_key END;
 IF n.data->>'subject_key' IS DISTINCT FROM subject OR o.data->>'subject_key' IS DISTINCT FROM subject OR n.valid_from>on_period OR n.valid_to<=on_period OR p.valid_from>on_period OR p.valid_to<=on_period OR o.valid_from>on_period OR o.valid_to<=on_period OR on_period<cutoff OR typ<>'CN_IIT'AND on_period<>cutoff OR typ='CN_IIT'AND extract(year FROM cutoff)<>extract(year FROM on_period)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税主体、期初截止或适用有效期不符';END IF;
 SELECT * INTO rel FROM public.ty_pay_config WHERE id=(SELECT relationship_config_id FROM public.ty_pay_row WHERE batch_id=b.id AND employment_id=e.id LIMIT 1);
 IF rel.id IS NULL THEN SELECT * INTO rel FROM public.ty_pay_config WHERE kind='relationship'AND status='approved'AND employment_id=e.id AND system=b.system AND valid_from<=b.period AND(valid_to IS NULL OR valid_to>=b.period+interval '1 month')ORDER BY revision DESC,id DESC LIMIT 1;END IF;
 IF rel.data->>'actual_employer_key' IS DISTINCT FROM n.data->>'actual_employer_key' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税资格不能借用另一实际法律雇主';END IF;
 IF EXISTS(SELECT 1 FROM public.ty_pay_stat_config newer WHERE newer.group_id=n.group_id AND newer.kind=n.kind AND newer.stable_key=n.stable_key AND newer.status='approved'AND newer.revision>n.revision AND newer.valid_from<=on_period AND(newer.valid_to IS NULL OR newer.valid_to>on_period))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税资格已有新生效版本';END IF;
 IF EXISTS(SELECT 1 FROM public.ty_pay_stat_config newer WHERE newer.group_id=p.group_id AND newer.kind=p.kind AND newer.stable_key=p.stable_key AND newer.status='approved'AND newer.revision>p.revision AND newer.valid_from<=on_period AND(newer.valid_to IS NULL OR newer.valid_to>on_period))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='政策已有新生效版本，须重核人员参保纳税映射';END IF;
 policy:=p.data;pp:=n.data->'periods'->to_char(on_period,'YYYY-MM');IF pp IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='本税款/供款期间人员参数未知，不能按零计算';END IF;
 -- Cash/tax/contribution recognition is by confirmed delta tranche and assigned
 -- period; earned-period ultimate targets remain separate for ADW.
 FOR j IN SELECT value FROM jsonb_array_elements(p_lines)WHERE(value->'scope'->>'person_id')::bigint=e.person_id AND EXISTS(SELECT 1 FROM public.ty_pay_config rc WHERE rc.id=coalesce((value->>'relationship_config_id')::bigint,(value->'source_snapshot'->>'relationship_config_id')::bigint)AND rc.kind='relationship'AND rc.status='approved'AND rc.employment_id=(value->'scope'->>'employment_id')::bigint AND rc.data->>'actual_employer_key'=n.data->>'actual_employer_key')LOOP
  SELECT(j->>'target')::numeric-coalesce(sum(a.delta),0)INTO v FROM public.ty_pay_adoption a JOIN public.ty_pay_obligation ob ON ob.id=a.obligation_id WHERE ob.group_id=b.group_id AND ob.economic_key=j->>'economic_key'AND a.state='confirmed'AND a.batch_id<>b.id;
  vals:=vals||jsonb_build_array(j||jsonb_build_object('stat_period',on_period,'target',v::text));
 END LOOP;
 FOR x IN SELECT a.id source_adoption_id,a.delta target,i.code,i.category,i.cash_wage_effect,i.wage_tags,ob.economic_key,oldb.id batch_id,oldb.period wage_period,oldb.tax_subject_key,oldb.contribution_subject_key,
   oldp.data period_data FROM public.ty_pay_adoption a JOIN public.ty_pay_obligation ob ON ob.id=a.obligation_id JOIN public.ty_pay_item i ON i.adoption_id=a.id JOIN public.ty_pay_row pr ON pr.id=i.row_id JOIN public.ty_pay_config rc ON rc.id=pr.relationship_config_id JOIN public.ty_pay_batch oldb ON oldb.id=a.batch_id
   LEFT JOIN LATERAL(SELECT data FROM public.ty_pay_stat_config WHERE kind='batch_period'AND status='approved'AND(data->>'batch_id')::bigint=oldb.id ORDER BY revision DESC,id DESC LIMIT 1)oldp ON true
   WHERE ob.group_id=b.group_id AND ob.person_id=e.person_id AND oldb.system=b.system AND oldb.status='confirmed'AND a.state='confirmed'AND oldb.id<>b.id 
   AND(CASE WHEN typ='CN_IIT'THEN oldb.tax_subject_key ELSE oldb.contribution_subject_key END)=subject
   AND rc.data->>'actual_employer_key'=n.data->>'actual_employer_key'
   ORDER BY a.id LOOP
  IF x.period_data IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一主体已有工资尚未核对支付/税供款期间，不得忽略或重复算期初';END IF;
  v:=NULL;IF typ='CN_IIT'THEN scope:=x.period_data->>'tax_period';ELSE scope:=x.period_data->>'contribution_period';END IF;
  IF scope::date<cutoff OR scope::date>on_period OR typ<>'CN_IIT'AND scope::date<>on_period THEN CONTINUE;END IF;
  vals:=vals||jsonb_build_array(jsonb_build_object('code',x.code,'target',x.target,'category',x.category,'cash_wage_effect',x.cash_wage_effect,'stat_period',scope,'economic_key',x.economic_key,'source_adoption_id',x.source_adoption_id));
 END LOOP;
 FOR j IN SELECT value FROM jsonb_array_elements(vals)LOOP
  scope:=policy->'scope_by_item'->>(j->>'code');
  IF scope IS NULL AND(j->>'category'='cash_earnings'OR j->>'cash_wage_effect'='decrease_gross')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税项目计入/排除范围未核定，不能把全部现金项目泛化或默认为零';END IF;
  IF scope='include'THEN v:=(j->>'target')::numeric;IF j->>'cash_wage_effect'='decrease_gross'THEN v:=-v;END IF;income:=income+v;END IF;
  IF typ='CN_IIT'AND policy->'deductible_codes' ? (j->>'code')THEN deductible:=deductible+(j->>'target')::numeric;END IF;
  IF NOT(j->>'stat_period'=ANY(periods))THEN periods:=array_append(periods,j->>'stat_period');END IF;
 END LOOP;
 IF NOT(to_char(on_period,'YYYY-MM-DD')=ANY(periods))THEN periods:=array_append(periods,to_char(on_period,'YYYY-MM-DD'));END IF;
 IF typ='CN_IIT'THEN
  IF n.data->>'cumulative_start_period'IS NULL OR(n.data->>'cumulative_start_period')::date<cutoff OR(n.data->>'cumulative_start_period')::date>on_period THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='累计费用资格起始月须明确核定，未知月份不能按零';END IF;
  SELECT array_agg(to_char(d,'YYYY-MM-DD')ORDER BY d)INTO periods FROM generate_series((n.data->>'cumulative_start_period')::date,on_period,interval '1 month')d;
  FOREACH scope IN ARRAY periods LOOP
  j:=n.data->'periods'->to_char(scope::date,'YYYY-MM');IF j IS NULL OR j->>'basic'IS NULL OR j->>'special'IS NULL OR j->>'other'IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='累计月份的基本费用/专项扣除参数缺失，不能反复按当月全额或补零';END IF;
  basic:=basic+(j->>'basic')::numeric;special:=special+(j->>'special')::numeric;other:=other+(j->>'other')::numeric;
 END LOOP;END IF;
 IF income<0 OR deductible<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税累计收入/扣除不能为负';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('economic_key',entry.value->>'economic_key','source_adoption_id',entry.value->>'source_adoption_id','code',entry.value->>'code','target',round((entry.value->>'target')::numeric,2)::text,'category',entry.value->>'category','cash_wage_effect',entry.value->>'cash_wage_effect','stat_period',entry.value->>'stat_period')ORDER BY entry.value->>'code',entry.value->>'economic_key',entry.value->>'stat_period',entry.value->>'source_adoption_id'),'[]'::jsonb)INTO vals FROM jsonb_array_elements(vals)entry;
 RETURN jsonb_build_object('type',typ,'policy',to_jsonb(p),'enrollment',to_jsonb(n),'opening',to_jsonb(o),'batch_period',to_jsonb(bp),'employment_id',e.id,'person_id',e.person_id,'group_id',b.group_id,'subject_key',subject,'legal_employer_key',n.data->>'actual_employer_key','period',on_period,'plan_key',n.data->>'plan_key','native_income',income::text,'native_deductible',deductible::text,'native_basic',basic::text,'native_special',special::text,'native_other',other::text,'period_parameters',pp,'wage_basis',vals);
END;$$;

CREATE FUNCTION fn_ty_pay_stat_math(c jsonb,p_component text)RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE p jsonb:=c->'policy'->'data';n jsonb:=c->'enrollment'->'data';o jsonb:=c->'opening'->'data';v jsonb:=c->'period_parameters';typ text:=c->>'type';side text;inc numeric;base numeric;lo numeric;hi numeric;rate numeric;cap numeric;tax numeric:=0;br jsonb;lower_bound numeric;upper_bound numeric;target numeric;initial numeric;eligible boolean;
BEGIN
 IF typ='CN_IIT'THEN
  IF p_component<>'CN_IIT_WITHHOLD'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个税计算不得改作其他应发项目';END IF;
  base:=greatest(0,(o->>'income')::numeric+(c->>'native_income')::numeric-(o->>'deductible')::numeric-(c->>'native_deductible')::numeric-(o->>'basic')::numeric-(c->>'native_basic')::numeric-(o->>'special')::numeric-(c->>'native_special')::numeric-(o->>'other')::numeric-(c->>'native_other')::numeric);
  FOR br IN SELECT value FROM jsonb_array_elements(p->'brackets')LOOP lower_bound:=(br->>'lower')::numeric;upper_bound:=(br->>'upper')::numeric;tax:=tax+greatest(0,least(base,coalesce(upper_bound,base))-lower_bound)*(br->>'rate')::numeric;END LOOP;
  target:=round(tax,2);initial:=(o->>'tax_recognized')::numeric;
 ELSIF typ IN('CN_SOCIAL','HK_MPF_REGULAR')THEN
  IF p_component=p->>'employee_code'THEN side:='employee';ELSIF p_component=p->>'employer_code'THEN side:='employer';ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定项目不属于本政策原子';END IF;
  IF jsonb_typeof(v->(side||'_eligible'))<>'boolean'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员资格未知不能推定零扣款';END IF;eligible:=(v->>(side||'_eligible'))::boolean;
  IF NOT eligible THEN RETURN jsonb_build_object('state','not_applicable','target',NULL,'initial',(o->>(side||'_target'))::numeric::text);END IF;
  lo:=(p->>'lower')::numeric;hi:=(p->>'upper')::numeric;rate:=(p->>(side||'_rate'))::numeric;
  IF typ='CN_SOCIAL'THEN base:=least(greatest((v->>'declared_base')::numeric,lo),hi);target:=round(base*rate,2);
  ELSE inc:=(o->>'income')::numeric+(c->>'native_income')::numeric;base:=least(inc,hi);cap:=(p->>(side||'_cap'))::numeric;target:=round(least(CASE WHEN side='employee'AND inc<lo THEN 0 ELSE base*rate END,cap),2);END IF;
  target:=target+round((v->>(side||'_arrears'))::numeric,2);initial:=(o->>(side||'_target'))::numeric;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税计算模板未实现，不能泛用普通月度MPF';END IF;
 IF target IS NULL OR initial IS NULL OR target<0 OR initial<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税参数缺失或非法，不能默认为零';END IF;
 RETURN jsonb_build_object('state',CASE WHEN target=0 THEN 'confirmed_zero'ELSE 'calculated'END,'target',target::text,'initial',initial::text,'base',base::text);
END;$$;

-- 217 calls these exact extension gates on actual final wage rows.
CREATE OR REPLACE FUNCTION fn_ty_pay_extension_key(p_batch bigint,p_adoption bigint)RETURNS text LANGUAGE plpgsql SET search_path='' AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;r public.ty_pay_row%ROWTYPE;root public.ty_pay_stat_root%ROWTYPE;item_code text;
BEGIN
 SELECT * INTO a FROM public.ty_pay_adoption WHERE id=p_adoption AND batch_id=p_batch;SELECT r0.* INTO r FROM public.ty_pay_row r0 JOIN public.ty_pay_item i ON i.row_id=r0.id WHERE i.adoption_id=a.id;SELECT * INTO root FROM public.ty_pay_stat_root WHERE id=(a.source_snapshot->>'stat_root_id')::bigint;
 SELECT code INTO item_code FROM public.ty_pay_item WHERE adoption_id=a.id;IF item_code IS DISTINCT FROM root.component THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定扣款或雇主成本不能被重标成现金应发';END IF;
 IF root.group_id<>r.group_id OR root.person_id<>r.person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税累计根不可搬人搬集团';END IF;RETURN root.global_key||':segment:'||r.employment_id;
END;$$;
CREATE OR REPLACE FUNCTION fn_ty_pay_extension_expected(p_batch bigint,p_adoption bigint)RETURNS numeric LANGUAGE plpgsql SET search_path='' AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;r public.ty_pay_row%ROWTYPE;b public.ty_pay_batch%ROWTYPE;root public.ty_pay_stat_root%ROWTYPE;c jsonb;m jsonb;lines jsonb;prior numeric;global_target numeric;
BEGIN
 SELECT * INTO a FROM public.ty_pay_adoption WHERE id=p_adoption AND batch_id=p_batch;SELECT r0.* INTO r FROM public.ty_pay_row r0 JOIN public.ty_pay_item i ON i.row_id=r0.id WHERE i.adoption_id=a.id;SELECT * INTO b FROM public.ty_pay_batch WHERE id=p_batch;SELECT * INTO root FROM public.ty_pay_stat_root WHERE id=(a.source_snapshot->>'stat_root_id')::bigint FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('economic_key',ob.economic_key,'code',i.code,'category',i.category,'cash_wage_effect',i.cash_wage_effect,'target',ad.target,'relationship_config_id',pr.relationship_config_id,'scope',jsonb_build_object('person_id',pr.person_id,'employment_id',pr.employment_id))), '[]'::jsonb)INTO lines FROM public.ty_pay_adoption ad JOIN public.ty_pay_obligation ob ON ob.id=ad.obligation_id JOIN public.ty_pay_item i ON i.adoption_id=ad.id JOIN public.ty_pay_row pr ON pr.id=i.row_id WHERE ad.batch_id=b.id AND ad.source_domain<>'statutory_calculation';
 -- Social contributions calculated earlier in the same batch are deductible for IIT.
 IF root.component='CN_IIT_WITHHOLD'THEN SELECT lines||coalesce(jsonb_agg(jsonb_build_object('economic_key',ob.economic_key,'code',i.code,'category',i.category,'cash_wage_effect',i.cash_wage_effect,'target',ad.target,'relationship_config_id',pr.relationship_config_id,'scope',jsonb_build_object('person_id',pr.person_id,'employment_id',pr.employment_id))),'[]'::jsonb)INTO lines FROM public.ty_pay_adoption ad JOIN public.ty_pay_obligation ob ON ob.id=ad.obligation_id JOIN public.ty_pay_item i ON i.adoption_id=ad.id JOIN public.ty_pay_row pr ON pr.id=i.row_id WHERE ad.batch_id=b.id AND ad.source_domain='statutory_calculation'AND i.code<>'CN_IIT_WITHHOLD';END IF;
 c:=public.fn_ty_pay_stat_context(b.id,r.employment_id,(a.source_snapshot->>'enrollment_id')::bigint,lines);IF a.source_snapshot->>'context_fingerprint' IS DISTINCT FROM md5(c::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='原生薪税依据、工资事实或政策版本已经改变';END IF;m:=public.fn_ty_pay_stat_math(c,root.component);
 IF c->>'subject_key'IS DISTINCT FROM root.subject_key OR c->>'plan_key'IS DISTINCT FROM root.plan_key OR c->>'legal_employer_key'IS DISTINCT FROM root.legal_employer_key OR (c->'opening'->>'id')::bigint<>root.opening_id OR root.head_revision<>(a.source_snapshot->>'root_revision')::int OR root.latest_period>(c->>'period')::date THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='薪税累计主体、期间、期初或版本头已变化，请重算';END IF;
 IF m->>'state'='not_applicable'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='不适用不等于0金额工资项目';END IF;
 global_target:=(m->>'target')::numeric;IF root.component='CN_IIT_WITHHOLD'THEN global_target:=greatest(global_target,root.current_target);END IF;
 SELECT coalesce(sum(delta),0)INTO prior FROM public.ty_pay_adoption WHERE obligation_id=a.obligation_id AND state='confirmed'AND batch_id<>b.id;
 IF global_target<>(a.source_snapshot->>'global_target')::numeric OR a.target<>prior+global_target-root.current_target THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定项目须由原生累计工资、已核政策资格与期初独立复算';END IF;RETURN a.target;
END;$$;
CREATE FUNCTION fn_ty_pay_stat_reserve()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE root public.ty_pay_stat_root%ROWTYPE;
BEGIN
 IF NEW.source_domain<>'statutory_calculation'THEN RETURN NEW;END IF;
 IF TG_OP='INSERT'THEN
  SELECT * INTO root FROM public.ty_pay_stat_root WHERE id=(NEW.source_snapshot->>'stat_root_id')::bigint FOR UPDATE;
  IF root.head_revision<>(NEW.source_snapshot->>'root_revision')::int THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='法定累计采用基线已变化';END IF;
  INSERT INTO public.ty_pay_stat_reservation VALUES(NEW.id,root.id,NEW.batch_id,root.head_revision,'reserved',(NEW.source_snapshot->>'global_target')::numeric,NEW.target,NEW.source_snapshot);
 ELSE UPDATE public.ty_pay_stat_reservation SET state=NEW.state WHERE adoption_id=NEW.id;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_stat_reserve AFTER INSERT OR UPDATE ON ty_pay_adoption FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_reserve();
CREATE FUNCTION fn_ty_pay_stat_confirm()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE x record;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 FOR x IN SELECT s.*,a.source_snapshot FROM public.ty_pay_stat_reservation s JOIN public.ty_pay_adoption a ON a.id=s.adoption_id WHERE s.batch_id=NEW.id ORDER BY root_id LOOP
  IF x.state<>'confirmed'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定工资采用未完整确认';END IF;
  UPDATE public.ty_pay_stat_root SET current_target=x.global_target,head_revision=head_revision+1,last_batch_id=NEW.id,latest_period=(x.source_snapshot->>'stat_period')::date,last_assessment=x.source_snapshot WHERE id=x.root_id AND head_revision=x.expected_revision;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='同一人员主体法定累计版本竞争，请重新核对';END IF;
 END LOOP;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_stat_confirm BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_confirm();
-- Reservation and accumulated bases are not manually editable ledgers.
CREATE FUNCTION fn_ty_pay_stat_reservation_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.ty_pay_adoption WHERE id=NEW.adoption_id;
 IF a.source_domain<>'statutory_calculation'OR a.batch_id<>NEW.batch_id OR(a.source_snapshot->>'stat_root_id')::bigint<>NEW.root_id OR(a.source_snapshot->>'root_revision')::int<>NEW.expected_revision OR(a.source_snapshot->>'global_target')::numeric<>NEW.global_target OR a.target<>NEW.local_target OR a.source_snapshot IS DISTINCT FROM NEW.assessment OR a.state<>NEW.state THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定累计占用须与真实采用、来源版本及状态一致';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-'state' IS DISTINCT FROM to_jsonb(OLD)-'state'OR OLD.state<>'reserved'OR NEW.state NOT IN('confirmed','released'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定占用只能随原采用确认或释放';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_stat_reservation_guard BEFORE INSERT OR UPDATE ON ty_pay_stat_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_reservation_guard();
CREATE OR REPLACE FUNCTION fn_ty_pay_stat_root_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE o public.ty_pay_stat_config%ROWTYPE;initial numeric;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定累计历史不能删除';END IF;
 IF TG_OP='INSERT'THEN
  SELECT * INTO o FROM public.ty_pay_stat_config WHERE id=NEW.opening_id;
  initial:=CASE WHEN NEW.component='CN_IIT_WITHHOLD'THEN(o.data->>'tax_recognized')::numeric WHEN NEW.component LIKE '%_EMP_%'THEN(o.data->>'employee_target')::numeric ELSE(o.data->>'employer_target')::numeric END;
  IF o.kind<>'opening'OR o.status<>'approved'OR o.group_id<>NEW.group_id OR o.person_id<>NEW.person_id OR o.data->>'subject_key'IS DISTINCT FROM NEW.subject_key OR NEW.head_revision<>0 OR NEW.last_batch_id IS NOT NULL OR NEW.latest_period IS NOT NULL OR NEW.current_target<>initial OR NEW.global_key IS DISTINCT FROM 'stat:'||NEW.group_id||':'||NEW.person_id||':'||NEW.subject_key||':'||NEW.legal_employer_key||':'||NEW.component||':'||to_char(NEW.period,'YYYY-MM-DD')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='累计初值只能来自同人同主体已核期初，计划别名不能新造上限';END IF;
 ELSE
  IF to_jsonb(NEW)-'head_revision'-'current_target'-'latest_period'-'last_batch_id'-'last_assessment' IS DISTINCT FROM to_jsonb(OLD)-'head_revision'-'current_target'-'latest_period'-'last_batch_id'-'last_assessment' OR NEW.head_revision<>OLD.head_revision+1 OR NOT EXISTS(SELECT 1 FROM public.ty_pay_stat_reservation s JOIN public.ty_pay_adoption a ON a.id=s.adoption_id WHERE s.root_id=NEW.id AND s.batch_id=NEW.last_batch_id AND s.state='confirmed'AND a.state='confirmed'AND s.expected_revision=OLD.head_revision AND s.global_target=NEW.current_target AND s.assessment=NEW.last_assessment AND(s.assessment->>'stat_period')::date=NEW.latest_period)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税主体累计根只能按已确认工资版本前进';END IF;
 END IF;RETURN NEW;
END;$$;
DROP TRIGGER ty_pay_stat_root_guard ON ty_pay_stat_root;
CREATE TRIGGER ty_pay_stat_root_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_stat_root FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_root_guard();
ALTER TABLE ty_pay_stat_root ADD CHECK(current_target<>'NaN'::numeric);
ALTER TABLE ty_pay_stat_reservation ADD CHECK(global_target<>'NaN'::numeric AND local_target<>'NaN'::numeric);
CREATE FUNCTION fn_ty_pay_stat_decimal(v text)RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$BEGIN
 IF v IS NULL OR v!~'^(0|[1-9][0-9]{0,23})(\.[0-9]{1,12})?$'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税政策参数须为明确非负有限十进制文本';END IF;RETURN v::numeric;
END;$$;
CREATE FUNCTION fn_ty_pay_stat_policy_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE d jsonb:=NEW.data;br jsonb;k text;v jsonb;next_lower numeric:=0;upper_bound numeric;rate numeric;last_rate numeric:=0;carry numeric:=0;n int:=0;total int;
BEGIN
 IF NEW.kind='policy'THEN
  IF d->>'type'NOT IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR')OR(d->>'type'IN('CN_IIT','CN_SOCIAL'))IS DISTINCT FROM(NEW.system='CN_PAYROLL')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税政策类型尚未实现';END IF;
  FOR k,v IN SELECT * FROM jsonb_each(d->'scope_by_item')LOOP IF v NOT IN('"include"'::jsonb,'"exclude"'::jsonb)OR NOT EXISTS(SELECT 1 FROM public.ty_pay_item_catalog WHERE code=k)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税工资范围必须逐目录项目明确核定';END IF;END LOOP;
  IF d->>'type'='CN_IIT'THEN
   total:=jsonb_array_length(d->'brackets');IF total IS NULL OR total<1 OR total>100 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='完整税率档不能为空';END IF;
   FOR br IN SELECT value FROM jsonb_array_elements(d->'brackets')LOOP
    n:=n+1;IF NOT(br ? 'upper')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='税档上限必须明确数值或null无上限，缺失不能猜';END IF;rate:=public.fn_ty_pay_stat_decimal(br->>'rate');upper_bound:=CASE WHEN br->>'upper'IS NULL THEN NULL ELSE public.fn_ty_pay_stat_decimal(br->>'upper')END;
    IF public.fn_ty_pay_stat_decimal(br->>'lower')<>next_lower OR rate>1 OR rate<last_rate OR upper_bound IS NOT NULL AND upper_bound<=next_lower OR n<total AND upper_bound IS NULL OR n=total AND upper_bound IS NOT NULL OR br ? 'quickDeduction'AND public.fn_ty_pay_stat_decimal(br->>'quickDeduction')<>next_lower*rate-carry THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='税档必须连续完整且税率/速算扣除相互一致';END IF;
    IF upper_bound IS NOT NULL THEN carry:=carry+(upper_bound-next_lower)*rate;next_lower:=upper_bound;END IF;last_rate:=rate;
   END LOOP;
  ELSE
   IF public.fn_ty_pay_stat_decimal(d->>'lower')>public.fn_ty_pay_stat_decimal(d->>'upper')OR public.fn_ty_pay_stat_decimal(d->>'employee_rate')>1 OR public.fn_ty_pay_stat_decimal(d->>'employer_rate')>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='社保供款率或上下限不合法';END IF;
   IF d->>'type'='CN_SOCIAL'AND jsonb_build_array(d->'employee_code',d->'employer_code')NOT IN('["CN_EMP_PENSION","CN_ER_PENSION"]'::jsonb,'["CN_EMP_MEDICAL","CN_ER_MEDICAL"]'::jsonb,'["CN_EMP_UNEMPLOYMENT","CN_ER_UNEMPLOYMENT"]'::jsonb,'[null,"CN_ER_WORK_INJURY"]'::jsonb,'[null,"CN_ER_MATERNITY"]'::jsonb,'["CN_EMP_HOUSING_FUND","CN_ER_HOUSING_FUND"]'::jsonb)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人代扣与雇主成本原子不可改作现金应发';END IF;
   IF d->>'type'='HK_MPF_REGULAR'AND(d->>'scheme_type'IS DISTINCT FROM 'regular'OR d->>'period_type'IS DISTINCT FROM 'monthly'OR d->>'employee_code'IS DISTINCT FROM 'HK_EMP_MPF_MANDATORY'OR d->>'employer_code'IS DISTINCT FROM 'HK_ER_MPF_MANDATORY')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业临时供款不能改标普通月度模板';END IF;
   IF d->>'type'='HK_MPF_REGULAR'THEN PERFORM public.fn_ty_pay_stat_decimal(d->>'employee_cap');PERFORM public.fn_ty_pay_stat_decimal(d->>'employer_cap');END IF;
  END IF;
 ELSIF NEW.kind='opening'THEN FOREACH k IN ARRAY ARRAY['income','deductible','basic','special','other','tax_recognized','employee_target','employer_target']LOOP PERFORM public.fn_ty_pay_stat_decimal(d->>k);END LOOP;
 ELSIF NEW.kind='enrollment'THEN
  FOR k,v IN SELECT * FROM jsonb_each(d->'periods')LOOP
   IF k!~'^[0-9]{4}-(0[1-9]|1[0-2])$'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='逐期人员参数键须YYYY-MM';END IF;
   IF v ? 'basic'THEN PERFORM public.fn_ty_pay_stat_decimal(v->>'basic');PERFORM public.fn_ty_pay_stat_decimal(v->>'special');PERFORM public.fn_ty_pay_stat_decimal(v->>'other');ELSE
    IF jsonb_typeof(v->'employee_eligible')IS DISTINCT FROM 'boolean'OR jsonb_typeof(v->'employer_eligible')IS DISTINCT FROM 'boolean'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资格必须明确核定而不是缺失/字符串';END IF;
    PERFORM public.fn_ty_pay_stat_decimal(v->>'employee_arrears');PERFORM public.fn_ty_pay_stat_decimal(v->>'employer_arrears');IF v ? 'declared_base'THEN PERFORM public.fn_ty_pay_stat_decimal(v->>'declared_base');END IF;
   END IF;
  END LOOP;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_stat_policy_guard BEFORE INSERT OR UPDATE ON ty_pay_stat_config FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_stat_policy_guard();
CREATE INDEX ty_pay_stat_config_person ON ty_pay_stat_config(group_id,person_id,kind,status);
CREATE INDEX ty_pay_stat_batch_period ON ty_pay_stat_config((data->>'batch_id'))WHERE kind='batch_period'AND status='approved';
-- Stored totals are presentation inputs to payslips: they must conserve the
-- actual typed wage items, not merely agree with another cached JSON value.
ALTER TABLE ty_pay_adoption ADD CHECK(target<>'NaN'::numeric AND prior_confirmed<>'NaN'::numeric AND delta<>'NaN'::numeric);
ALTER TABLE ty_pay_item ADD CHECK(amount<>'NaN'::numeric);
ALTER TABLE ty_pay_cost_entry ADD CHECK(amount<>'NaN'::numeric);
ALTER TABLE ty_pay_wage_day ADD CHECK(eligible_wages<>'NaN'::numeric AND excluded_wages<>'NaN'::numeric AND excluded_days<>'NaN'::numeric AND ordinary_wages<>'NaN'::numeric);
CREATE FUNCTION fn_ty_pay_totals_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_pay_row%ROWTYPE;s record;expected jsonb;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 FOR r IN SELECT * FROM public.ty_pay_row WHERE batch_id=NEW.id LOOP
  SELECT coalesce(sum(amount)FILTER(WHERE category='cash_earnings'),0)earnings,
   coalesce(sum(amount)FILTER(WHERE cash_wage_effect='decrease_gross'),0)reductions,
   coalesce(sum(amount)FILTER(WHERE category='personal_deduction'),0)deductions,
   coalesce(sum(amount)FILTER(WHERE category='employee_withholding'),0)withholding,
   coalesce(sum(amount)FILTER(WHERE category='reimbursement'),0)reimbursement,
   coalesce(sum(amount)FILTER(WHERE category='employer_cost'),0)employer,
   coalesce(sum(amount)FILTER(WHERE category='noncash_shadow'),0)noncash,
   coalesce(sum(amount)FILTER(WHERE category='agency_funds'),0)agency,
   coalesce(sum(amount)FILTER(WHERE category='restricted_payment_funds'),0)restricted,
   coalesce(sum(amount)FILTER(WHERE category='procurement_service'),0)procurement INTO s FROM public.ty_pay_item WHERE row_id=r.id;
  expected:=jsonb_build_object('cash_earnings_before_reduction',round(s.earnings,2)::text,'wage_reductions',round(s.reductions,2)::text,'cash_gross',round(s.earnings-s.reductions,2)::text,'personal_deductions',round(s.deductions-s.reductions,2)::text,'employee_withholding',round(s.withholding,2)::text,'reimbursement',round(s.reimbursement,2)::text,'net_wage_payable',round(s.earnings-s.deductions-s.withholding,2)::text,'employee_cash_settlement',round(s.earnings-s.deductions-s.withholding+s.reimbursement,2)::text,'employer_additional_cost',round(s.employer,2)::text,'noncash_shadow',round(s.noncash,2)::text,'agency_funds',round(s.agency,2)::text,'restricted_payment_funds',round(s.restricted,2)::text,'procurement_service',round(s.procurement,2)::text,'payment_status','not_instructed');
  IF NOT(r.totals @> expected)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资单汇总必须与真实项目逐账册守恒，不能伪造应发/净额/成本';END IF;
 END LOOP;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_totals_guard BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_totals_guard();
-- ADW is an earned-month final target, unlike tax/MPF recognition tranches.
-- A later bonus or base-only correction must not erase an earlier earned item.
CREATE OR REPLACE FUNCTION fn_ty_pay_wage_day_confirm()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_pay_row%ROWTYPE;e public.ty_employment%ROWTYPE;target numeric;actual numeric;n int;expected int;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'OR NEW.system<>'HK_PAYROLL'THEN RETURN NEW;END IF;
 FOR r IN SELECT * FROM public.ty_pay_row WHERE batch_id=NEW.id AND employment_id IS NOT NULL LOOP
  IF NOT EXISTS(SELECT 1 FROM public.ty_pay_item WHERE row_id=r.id AND(category='cash_earnings'OR cash_wage_effect='decrease_gross'))THEN CONTINUE;END IF;
  SELECT sum(x.target*CASE WHEN x.cash_wage_effect='decrease_gross'THEN -1 ELSE 1 END)FILTER(WHERE x.wage_tags->>'hk_adw'='include'),count(*)FILTER(WHERE coalesce(x.wage_tags->>'hk_adw','pending')NOT IN('include','exclude','not_applicable'))INTO target,n FROM(
   SELECT DISTINCT ON(a.obligation_id)a.target,i.cash_wage_effect,i.wage_tags FROM public.ty_pay_item i JOIN public.ty_pay_adoption a ON a.id=i.adoption_id JOIN public.ty_pay_obligation o ON o.id=a.obligation_id JOIN public.ty_pay_batch b ON b.id=a.batch_id
   WHERE o.group_id=NEW.group_id AND o.employment_id=r.employment_id AND b.system='HK_PAYROLL'AND b.period=NEW.period AND(b.status='confirmed'OR b.id=NEW.id)AND a.state='confirmed'AND(i.category='cash_earnings'OR i.cash_wage_effect='decrease_gross')ORDER BY a.obligation_id,a.id DESC)x;
  IF n>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资月仍有ADW范围未核项目';END IF;target:=coalesce(target,0);SELECT * INTO e FROM public.ty_employment WHERE id=r.employment_id;
  expected:=least(coalesce(e.leave_date+1,(NEW.period+interval '1 month')::date),(NEW.period+interval '1 month')::date)-greatest(e.hire_date,NEW.period);
  SELECT sum(eligible_wages),count(*)INTO actual,n FROM public.ty_pay_wage_day WHERE row_id=r.id;
  IF actual IS DISTINCT FROM target OR n<>expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生工资窗须完整覆盖该雇佣工资月所有义务最终目标，补差不得抹掉旧奖金';END IF;
 END LOOP;RETURN NEW;
END;$$;
CREATE FUNCTION fn_ty_pay_source_treatments_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE book public.ty_pay_config%ROWTYPE;x record;tags jsonb;k text;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;SELECT * INTO book FROM public.ty_pay_config WHERE id=NEW.rulebook_id;
 FOR x IN SELECT i.code,i.wage_tags,a.source_domain FROM public.ty_pay_item i JOIN public.ty_pay_adoption a ON a.id=i.adoption_id WHERE a.batch_id=NEW.id AND a.source_domain NOT IN('payroll_calculation','statutory_calculation')AND(i.category='cash_earnings'OR i.cash_wage_effect='decrease_gross')LOOP
  tags:=book.data->'source_treatments'->x.source_domain->x.code;IF tags ? 'wage_tags'THEN tags:=tags->'wage_tags';END IF;
  FOREACH k IN ARRAY ARRAY['hk_adw','cn_average','cn_annual_leave','ordinary_wage']LOOP
   IF tags ? k THEN IF tags->>k NOT IN('include','exclude','not_applicable')OR x.wage_tags->>k IS DISTINCT FROM tags->>k THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='来源工资范围必须符合本批已批准待遇版本';END IF;
   ELSIF x.wage_tags->>k IN('include','exclude','not_applicable')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='来源工资范围未经待遇规则核定，不能自行标记';END IF;
  END LOOP;
 END LOOP;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_source_treatments_guard BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_source_treatments_guard();
